import json
from src.nodes.base import BaseNode
from src.runtime.reality import get_support_rule_engine

_EMPTY = {"support_json": "{}", "violations_json": "[]", "ok": False,
          "violation_count": 0, "exec_out": True}

class Hou_Mcp_Support_Validation(BaseNode):
    name = "hou_mcp_support_validation"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("scene_layout_json", "string", widget_type="text", default="{}")
        self.add_output("support_json")
        self.add_output("violations_json")
        self.add_output("ok", "bool")
        self.add_output("violation_count", "int")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        try:
            scene = json.loads((inputs.get("scene_layout_json") or "{}").strip() or "{}")
        except Exception:
            self.log_error("scene_layout_json is not valid JSON.")
            return dict(_EMPTY)
        try:
            result = get_support_rule_engine().check_scene(scene)
            for f in result.findings:
                self.log_error(f)
            return {
                "support_json": json.dumps(result.to_dict(), sort_keys=True, indent=2),
                "violations_json": json.dumps([v.to_dict() for v in result.violations], sort_keys=True, indent=2),
                "ok": result.ok,
                "violation_count": len(result.violations),
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Support validation failed: {exc}")
            return dict(_EMPTY)

def register_node():
    return Hou_Mcp_Support_Validation
